        int x1 = scanner.nextInt();
        int x2 = scanner.nextInt();
        int x3 = scanner.nextInt();
        scanner.close();

        int[] points = {x1, x2, x3};
        // Sort the points
        int min = Math.min(points[0], Math.min(points[1], points[2]));
        int max = Math.max(points[0], Math.max(points[1], points[2]));
        int mid = points[0] + points[1] + points[2] - min - max;

        // The optimal meeting point is the median (middle value)
        // Total distance = (max - mid) + (mid - min) = max - min
        int totalDistance = max - min;

        System.out.println(totalDistance);
    }
}
